prepare.command:
cd /app/packages/twenty-server && node <<'OPENSHIP_JS'
const { execFileSync } = require("child_process");
const bcrypt = require("bcrypt");
const E = process.env;
const url = "http://127.0.0.1:3000/metadata";
const email = E.TWENTY_ADMIN_EMAIL;
const full = E.TWENTY_ADMIN_PASSWORD;
const short = full.slice(0, 50);
const origin = E.SERVER_URL;
const q = async (query, variables, token) => {
  const r = await fetch(url, {
    method: "POST",
    headers: { "content-type": "application/json", ...(token ? { authorization: "Bearer " + token } : {}) },
    body: JSON.stringify({ query, variables }),
  });
  const j = await r.json();
  if (j.errors) throw new Error(j.errors[0].message);
  return j.data;
};
const agnostic = "tokens{accessOrWorkspaceAgnosticToken{token}}";
const signIn = (p) =>
  q("mutation($e:String!,$p:String!){signIn(email:$e,password:$p){" + agnostic + "}}", { e: email, p }).then(
    (d) => d.signIn.tokens.accessOrWorkspaceAgnosticToken.token,
    () => null,
  );
const loginToken = (p) =>
  q(
    "mutation($e:String!,$p:String!,$o:String!){getLoginTokenFromCredentials(email:$e,password:$p,origin:$o){loginToken{token}}}",
    { e: email, p, o: origin },
  ).then(
    (d) => d.getLoginTokenFromCredentials.loginToken.token,
    () => null,
  );
(async () => {
  let cur = short;
  let t = await signIn(short);
  if (!t) {
    cur = full;
    t = await signIn(full);
  }
  if (!t) {
    cur = short;
    const d = await q("mutation($e:String!,$p:String!){signUp(email:$e,password:$p){" + agnostic + "}}", {
      e: email,
      p: short,
    });
    t = d.signUp.tokens.accessOrWorkspaceAgnosticToken.token;
  }
  let lt = await loginToken(cur);
  if (!lt) {
    const w = await q(
      "mutation($n:String!){signUpInNewWorkspace(input:{displayName:$n}){loginToken{token}}}",
      { n: "Openship" },
      t,
    );
    lt = w.signUpInNewWorkspace.loginToken.token;
  }
  const s = await q(
    "mutation($l:String!,$o:String!){getAuthTokensFromLoginToken(loginToken:$l,origin:$o){" + agnostic + "}}",
    { l: lt, o: origin },
  );
  const x = s.getAuthTokensFromLoginToken.tokens.accessOrWorkspaceAgnosticToken.token;
  const c = await q("{currentWorkspace{activationStatus}}", undefined, x);
  if (c.currentWorkspace.activationStatus !== "ACTIVE") {
    await q(
      "mutation($n:String!){activateWorkspace(data:{displayName:$n}){id activationStatus}}",
      { n: "Openship" },
      x,
    );
  }
  const hash = await bcrypt.hash(full, 10);
  execFileSync("psql", [E.PG_DATABASE_URL, "-v", "ON_ERROR_STOP=1", "-q", "-v", "h=" + hash, "-v", "e=" + email, "-f", "-"], {
    input: 'UPDATE core."user" SET "passwordHash" = :\'h\' WHERE lower(email) = lower(:\'e\');\n',
  });
  console.log("twenty administrator ready");
})().catch((x) => {
  console.error("ERR:", x.message);
  process.exit(1);
});
OPENSHIP_JS
